/**
 * Packages the Cloudflare Worker entry point (src/index.ts) into a single
 * ES module string using esbuild in-memory bundling.
 */

import fs from 'node:fs'

import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

import { build } from 'esbuild'

const __dirname = dirname(fileURLToPath(import.meta.url))

/**
 * Lazily loads the pre-compiled fallback bundle.
 *
 * `src/bundle-code.ts` is a build artifact (gitignored, regenerated by
 * `pnpm build`). It may be absent on fresh clones — that must never break
 * module load, so this resolves to an empty string instead of throwing.
 * Types come from the committed `src/bundle-code.d.ts`.
 */
async function loadBundledFallback(): Promise<string> {
  try {
    const mod = await import('../bundle-code') as { BUNDLED_WORKER_SCRIPT?: unknown }
    if (typeof mod.BUNDLED_WORKER_SCRIPT !== 'string' || mod.BUNDLED_WORKER_SCRIPT.length === 0)
      return ''
    // Guard against stale code-split artifacts: a valid fallback is a single
    // self-contained module. A chunk import means the file was generated by an
    // old multi-file build and would fail Cloudflare upload validation (10021).
    if (/\bfrom\s+["']\.\/[^"']+\.mjs["']/.test(mod.BUNDLED_WORKER_SCRIPT))
      return ''
    return mod.BUNDLED_WORKER_SCRIPT
  }
  catch {
    return ''
  }
}

/**
 * Upload-time tripwire for packaged worker code. esbuild bundling can fail
 * silently in environments without native deps (packaged Electron apps,
 * partial installs) and the prebuilt fallback can be an empty placeholder —
 * uploading either as the worker with Durable Object bindings attached
 * produces Cloudflare error 10061 ("Cannot create binding for class ...
 * that is not exported by the script"). Fail loudly here instead of
 * uploading garbage the API will reject.
 *
 * Returns an actionable error message, or null when the code is uploadable.
 */
export function validateWorkerScriptForUpload(code: string, requiredClass?: string): string | null {
  if (!code || code.trim().length === 0) {
    return 'Worker script bundle is empty: esbuild packaging failed and no prebuilt fallback exists. '
      + 'On a dev machine, run `pnpm install` then `pnpm --filter @proj-airi/stage-edge build` and retry. '
      + 'Inside a packaged app, deploy from a full checkout instead.'
  }
  if (requiredClass && !code.includes(requiredClass)) {
    return `Worker script does not export the Durable Object class '${requiredClass}' but the upload binds it. `
      + 'The bundle is stale or truncated — rebuild with `pnpm --filter @proj-airi/stage-edge build` and retry.'
  }
  return null
}

export async function packageWorkerScript(): Promise<string> {
  try {
    const candidates = [
      resolve(__dirname, '../index.ts'),
      resolve(__dirname, 'index.ts'),
      resolve(__dirname, '../index.mjs'),
      resolve(__dirname, 'index.mjs'),
      resolve(__dirname, '../src/index.ts'),
    ]

    const entryPoint = candidates.find(c => fs.existsSync(c))
    if (entryPoint) {
      const result = await build({
        entryPoints: [entryPoint],
        bundle: true,
        write: false,
        format: 'esm',
        target: 'es2022',
        platform: 'browser',
        external: [],
      })

      const outputFile = result.outputFiles[0]
      if (outputFile) {
        return outputFile.text
      }
    }
  }
  catch (err: any) {
    console.warn(`[Packager] Dynamic bundle attempt failed, using pre-bundled fallback script: ${err.message}`)
  }

  // Guaranteed zero-fail fallback: pre-compiled full worker bundle code!
  return loadBundledFallback()
}
